\label{diagram}
\centering
\begin{tikzpicture}[node distance=2cm]
\footnotesize

\node (1)[startstop, yshift=0cm, fill=white!20]{\underline{Conjecture \ref{conj:weak}} \\ Hypergraph Nash-Williams--Tutte Conjecture};
\node (2)[startstop, right of =1, xshift=3cm,fill=white!20]{\underline{Conjecture \ref{conjecture}}\\ Nonsingularity of intersection matrices};
\node (3)[startstop, right of =2, xshift=3cm,fill=white!20]{\underline{Conjecture \ref{conjecture-0}}\\ Optimal List Decoding of RS Codes};
\draw [arrow] (1) --node[anchor=south] {Thm. \ref{thm:complete-2}}(2);
\draw [arrow] (2) --node[anchor=south] {\cite{shangguan2019combinatorial0} }(3);




\node (0)[startstop, above of=1, yshift=3cm,fill=white!20]{\underline{Lemma \ref{Nash-Williams}}\\ Nash-Williams--Tutte theorem \cite{nash1961edge,tutte1961problem}.};

\node (7)[startstop, right of=0, xshift=3cm,fill=white!20]{\underline{Theorem \ref{theorem-weaker}}\\ Nonsingularity of intersection matrices, provided that $I_i \cap I_j \cap I_\ell = \emptyset$ for all distinct $i,j,l$.};


\node (9)[startstop,  thick, right of =7, xshift=3cm,fill=white!20]{\underline{Theorem \ref{thm:main}} \\Main Theorem: List Recovery of RS codes};
\draw [arrow] (0)--(7);
\draw [arrow] (7)--(9);
\node (8)[startstop, thick, above of =9, yshift=0.5cm,fill=white!20]{\underline{Theorem \ref{perfect-hash-matrix}} \\Existence of strongly perfect hash matrices};
\draw [arrow] (7) |-(8);


\node (6)[startstop, thick, below of =9, xshift=0cm,yshift= -0.5cm,fill=white!50!white!20]{\underline{Theorem \ref{thm:main-LD}}\\ List Decoding of RS codes };
\draw [arrow] (9) --(6);



\node [left of =1,color=red!70!black,anchor=east]
{\begin{minipage}{3cm} \begin{center} Proposed roadmap to optimal list-decoding, presented in Section~\ref{sec:conjectures}.
\end{center}\end{minipage}};
\node [left of =0,color=green!50!black,anchor=east]
{\begin{minipage}{3cm}
\begin{center}
Our proof of Theorem~\ref{thm:main-LD}, presented in Sections~\ref{sec:3},~\ref{phf},~\ref{list-recovery}
\end{center}\end{minipage}};


\draw[dashed] (1) to (0);
\draw[dashed] (2) to (7);
\draw[dashed] (3) to (6);
\end{tikzpicture}

\caption{
A diagram of the results and conjectures presented in this work.
Solid arrows represent logical implications.
Dashed lines indicate how the proposed roadmap to optimal list decoding parallels our proof of Theorem~\ref{thm:main-LD}.
}\label{fig:M1}
\end{figure*}

